package main

import (
	"fmt"
	"math/rand"
	"os"
	"runtime"
	"strings"
	"time"
)

func main() {
	fmt.Println(strings.Repeat("=", 40))
	fmt.Println("        Go System Info Tool")
	fmt.Println(strings.Repeat("=", 40))

	// OS & Runtime info
	fmt.Printf("\nOS       : %s\n", runtime.GOOS)
	fmt.Printf("Arch     : %s\n", runtime.GOARCH)
	fmt.Printf("CPUs     : %d\n", runtime.NumCPU())
	fmt.Printf("Go ver   : %s\n", runtime.Version())

	// Current time
	now := time.Now()
	fmt.Printf("Time     : %s\n", now.Format("2006-01-02 15:04:05"))
	fmt.Printf("Weekday  : %s\n", now.Weekday())

	// Hostname
	host, err := os.Hostname()
	if err != nil {
		host = "(unknown)"
	}
	fmt.Printf("Hostname : %s\n", host)

	// Fun random quote
	quotes := []string{
		"Don't communicate by sharing memory; share memory by communicating.",
		"Channels orchestrate; mutexes serialize.",
		"Make it work, make it right, make it fast.",
		"Simplicity is the soul of efficiency.",
		"A little copying is better than a little dependency.",
	}
	rand.New(rand.NewSource(now.UnixNano()))
	fmt.Printf("\nQuote    : \"%s\"\n", quotes[rand.Intn(len(quotes))])

	fmt.Println(strings.Repeat("=", 40))
}
